def diff_grids(g1, g2):
    """Return list of (r, c, old_val, new_val) for all differing cells"""
    diffs = []
    h1, w1 = len(g1), len(g1[0])
    h2, w2 = len(g2), len(g2[0])

    # Check dimensions match
    if h1 != h2 or w1 != w2:
        print(f"Dimension mismatch: {h1}x{w1} vs {h2}x{w2}")

    for r in range(max(h1, h2)):
        for c in range(max(w1, w2)):
            v1 = g1[r][c] if r < h1 and c < w1 else None
            v2 = g2[r][c] if r < h2 and c < w2 else None
            if v1 != v2:
                diffs.append((r, c, v1, v2))
    return diffs

