# New hypothesis: Keep ONLY the HIGHEST-SCORE component from each color group
# Then fill its bbox with that color

def top_component_per_color(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if (r,c) not in visited and grid[r][c] != 3:
                val = grid[r][c]
                q = [(r,c)]
                comp_cells = []
                visited.add((r,c))

                idx = 0
                while idx < len(q):
                    cr, cc = q[idx]; idx += 1
                    comp_cells.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == val and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            q.append((nr,nc))

                rs, cs = min(row for row,_ in comp_cells), min(col for _,col in comp_cells)
                re, ce = max(row for row,_ in comp_cells), max(col for _,col in comp_cells)
                expected = (re-rs+1)*(ce-cs+1)
                ratio = len(comp_cells) / expected
                score = len(comp_cells) * ratio

                comps.append({'val': val, 'area': len(comp_cells), 
                             'bbox': (rs,cs,re,ce), 'ratio': ratio, 'score': score})

    # Get highest-scored component per color
    best_by_val = {}
    for c in comps:
        if c['val'] not in best_by_val or c['score'] > best_by_val[c['val']]['score']:
            best_by_val[c['val']] = c

    return sorted(best_by_val.values(), key=lambda x: -x['score'])

